const chunks = split(doc, { size: 800, overlap: 100 });
const vectors = await embed(chunks);
await store.upsert(chunks.map((c, i) => ({ id: i, text: c, vector: vectors[i] })));

const hits = await store.search(await embedOne(question), { k: 5 });
const answer = await llm(`아래 발췌만 근거로 답하라:\n${hits.map((h) => h.text).join('\n---\n')}\n\n질문: ${question}`);
